package com.bsrubacky.tapeeater.api.lastFMimport com.bsrubacky.tapeeater.api.DataOrchestratorimport com.bsrubacky.tapeeater.api.OrchestratorResponseimport com.tickaroo.tikxml.retrofit.TikXmlConverterFactoryimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.withContextimport okio.IOExceptionimport retrofit2.Retrofitobject LastFMDataOrchestrator : DataOrchestrator<LastFM>() {    override val retrofit: Retrofit = Retrofit.Builder()        .client(okHttpClient)        .baseUrl("http://ws.audioscrobbler.com/2.0")        .addConverterFactory(TikXmlConverterFactory.create())        .build()    override suspend fun requestData(        vararg requests: LastFMRequest<*>    ): OrchestratorResponse<Int> =        withContext(Dispatchers.IO) {            try {                val api = retrofit.create(LastFM::class.java)                requests.forEach {                    it.setupRequest(api)                    it.run()                }            } catch (e: IOException) {                e.printStackTrace()                return@withContext OrchestratorResponse.Error(e)            }            return@withContext OrchestratorResponse.Success(200)        }}